Write-Host "Zatrzymywanie zajętych portów (5173, 8000)..." -ForegroundColor Yellow; $ports = @(5173, 8000); foreach ($port in $ports) { $conns = Get-NetTCPConnection -LocalPort $port -ErrorAction SilentlyContinue; if ($conns) { $pids = $conns | Select-Object -ExpandProperty OwningProcess -Unique; foreach ($id in $pids) { Stop-Process -Id $id -Force -ErrorAction SilentlyContinue } } }; Write-Host "Restartowanie serwisów Docker (Redis, Celery)..." -ForegroundColor Yellow; docker compose restart; Write-Host "Uruchamianie Backendu..." -ForegroundColor Green; Start-Process powershell -ArgumentList "-NoExit -Command `"cd backend; poetry run uvicorn main:app --reload --port 8000`""; Write-Host "Uruchamianie Frontendu..." -ForegroundColor Green; Start-Process powershell -ArgumentList "-NoExit -Command `"cd frontend; npm run dev`""; Write-Host "Gotowe! Uruchomiono nowe okna." -ForegroundColor Cyan
